 "content": "from functools import lru_cache

# Each local tile is a complete 2x2 square or a 3-cell L. The L's
# output color identifies its missing corner.
L_COLORS = {
    (0, 0): 2,  # missing top-left
    (0, 1): 4,  # missing top-right
    (1, 0): 3,  # missing bottom-left
    (1, 1): 5,  # missing bottom-right (not seen in demonstrations)
}


def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    if not cells:
        return [row[:] for row in grid]

    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            block = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if block <= cells:
                tiles.append((block, 1))
            for missing, color in L_COLORS.items():
                shape = block - {(r + missing[0], c + missing[1])}
                if shape <= cells:
                    tiles.append((shape, color))

    by_cell = {p: [] for p in cells}
    for shape, color in tiles:
        for p in shape:
            by_cell[p].append((shape, color))

    @lru_cache(None)
    def cover(remaining):
        remaining = frozenset(remaining)
        if not remaining:
            return ()
        p = min(remaining)
        for shape, color in by_cell[p]:
            if shape <= remaining:
                rest = cover(frozenset(remaining - shape))
                if rest is not None:
                    return ((shape, color),) + rest
        return None

    solution = cover(frozenset(cells))
    if solution is None:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    for shape, color in solution:
        for r, c in shape:
            out[r][c] = color
    return out
